export interface ConnectorConfig {
  trelloApiKey: string
  trelloToken: string
  checklistId: string
  fetch?: typeof fetch
}

export interface GoogleCalendarWebhookPayload {
  event: string
  event_id: string
  account_id: string
  attendees: Array<{ email: string }>
}

export interface HandleResult {
  checklistItemId: string
  checklistItemName: string
  checklistItemUri: string
}

export async function handle(
  payload: GoogleCalendarWebhookPayload,
  config: ConnectorConfig,
): Promise<HandleResult> {
  const fetchFn = config.fetch ?? fetch

  if (!payload.attendees || payload.attendees.length === 0) {
    throw new Error('No attendees found in the webhook payload')
  }

  const firstAttendee = payload.attendees[0]
  if (!firstAttendee.email) {
    throw new Error('First attendee is missing an email address')
  }

  const email = firstAttendee.email
  const url = `https://api.trello.com/1/checklists/${encodeURIComponent(config.checklistId)}/checkItems`

  const params = new URLSearchParams()
  params.set('key', config.trelloApiKey)
  params.set('token', config.trelloToken)
  params.set('value', email)

  const response = await fetchFn(`${url}?${params.toString()}`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
    },
  })

  if (!response.ok) {
    throw new Error(`Trello API error: ${response.status} ${response.statusText} for POST ${url}`)
  }

  const data = (await response.json()) as {
    id: string
    idChecklist: string
    state: string
    name: string
    uri: string
  }

  return {
    checklistItemId: data.id,
    checklistItemName: data.name,
    checklistItemUri: data.uri,
  }
}

